WITH unpacked AS (SELECT id, plan, effective_from, currency, tier_limits, tier_prices, discounts, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE plan = 'starter') SELECT *, LEAD(avg_tier_price, 2, 0) OVER (ORDER BY effective_from ASC, id ASC) AS next_avg_tier_price, SUM(avg_tier_price) OVER (PARTITION BY YEAR(effective_from), plan ORDER BY effective_from ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_tier_price, LAG(avg_tier_price, 1) OVER (PARTITION BY currency, plan ORDER BY avg_tier_price ASC, id ASC) AS prev_avg_tier_price, NTILE(10) OVER (PARTITION BY DATE_TRUNC('YEAR', effective_from), currency ORDER BY avg_tier_price DESC, id ASC) AS avg_tier_price_bucket FROM unpacked;
